function frontHTML(){return `<section class="panel"><h2>หน้าร้าน • ออเดอร์และการรับเงิน</h2><p>ยอดแต่ละออเดอร์คงตามข้อมูลขณะส่ง • สลิปและการรับเงิน <span class="tag">จำลอง</span></p><div data-testid="front-orders">${s.orders.map(o=>{const p=payment(o),old=o.session_id&&s.sessions.find(x=>x.id===o.session_id)?.state==='"'closed';return "'`<article data-testid="front-order" data-order-id="${o.id}" data-table-id="${esc(o.table_id)}" class="ticket"><div class="split"><h3>#${o.id} · ${o.channel==='"'takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class=\"status\">"'${statuses[o.status]}</span></div><small>${o.received_at} · ${esc(o.session_id||o.pickup_date+'"' '+o.pickup_slot)} "'${old?'"'· ประวัติรอบที่ปิดแล้ว':''}</small>"'${itemsHTML(o)}<div class="split"><strong data-testid="front-total" class="amount">${money(o.total)}</strong><strong data-testid="front-payment-status">${p.state}</strong></div><p>วิธีที่เลือก: ${p.method==='"'cash'?'เงินสด':p.method==='promptpay'?'PromptPay จำลอง':'ยังไม่เลือก'}</p><div class=\"row\">"'${button('"'btn-confirm-slip','ยืนยันสลิปจำลอง','confirm-slip',"'`data-id="${o.id}" ${p.state==='"'จ่ายแล้ว'||p.requested_at===null?'disabled':''}"'`)}${button('"'btn-receive-cash','รับเงินสดจำลอง','receive-cash',"'`data-id="${o.id}" ${p.state==='"'จ่ายแล้ว'?'disabled':''}"'`)}</div></article>`;}).join('"'')||'<p class=\"empty\">ยังไม่มีออเดอร์</p>'}</div></section><section class=\"panel\"><h2>รอบโต๊ะ</h2><label>เลือกโต๊ะ<select data-testid=\"front-table-select\">"'${choices(s.tables,u.frontTable,'"'table_id','label')}</select></label><p>"'${s.sessions.filter(x=>x.table_id===u.frontTable&&x.state==='"'open').map(x=>esc(x.id)+' · เปิดรอบ').join('')||'ไม่มีรอบที่เปิดอยู่'}</p><div class=\"row\">"'${button('"'','เปิดรอบโต๊ะจำลอง','front-open')}"'${button('"'btn-close-table','ปิดรอบโต๊ะที่เลือก','close-table','class=\"danger\"')}</div><p class=\"muted\">ปิดแล้วสั่งต่อรอบเดิมไม่ได้ เก็บออเดอร์เก่าในประวัติ • mock ไม่บังคับจ